// src/put-to-s3.ts
async function putToS3(Key, Body) {
  const client = new S3({
    region: process.env.AWS_REGION
  });
  try {
    await client.putObject({
      Bucket: process.env.AWS_BUCKET,
      Key,
      Body,
      ContentEncoding: "base64"
    });
    info(`\u2B06\uFE0F Uploaded ${Key} to S3.`);
  } catch (error2) {
    setFailed(error2.message);
  }
}

